 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Colored centers in plus-shaped 3-marker objects launch rays. Their own
    # four 3 arms are pass-through, but any other occupied cell stops a ray.
    sources = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] not in (0, 3) and
                grid[r - 1][c] == grid[r + 1][c] ==
                grid[r][c - 1] == grid[r][c + 1] == 3):
                own_arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
                sources.append((r, c, grid[r][c], own_arms))

    def cast(r, c, dr, dc, color, own_arms):
        y, x = r + dr, c + dc
        while 0 <= y < h and 0 <= x < w:
            if grid[y][x] != 0 and (y, x) not in own_arms:
                break
            if grid[y][x] == 0:
                out[y][x] = color
            y += dr
            x += dc

    # Horizontal rays first; vertical rays have priority at crossings.
    for r, c, color, arms in sources:
        cast(r, c, 0, -1, color, arms)
        cast(r, c, 0, 1, color, arms)
    for r, c, color, arms in sources:
        cast(r, c, -1, 0, color, arms)
        cast(r, c, 1, 0, color, arms)
    return out

